const $=s=>document.querySelector(s);const won=n=>n.toLocaleString('ko-KR')+'원';function read(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}function save(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}let checked=read('safekit-check',[]),cart=read('safekit-cart',{});
const checks=[['식량과 식수','보관이 편한 식품 · 식수'],['손전등과 건전지','어둠에 대비할 조명 · 여분 배터리'],['라디오와 보조배터리','공식 방송 수신 · 휴대전화 충전'],['구급용품과 개인 필요 물품','기본 응급용품 · 개인별 필요 확인'],['보온·위생용품','담요 · 여벌 옷 · 위생용품'],['가족 연락 계획과 중요 정보','연락처 · 만날 장소 · 대피소 확인']];
$('#checklist').innerHTML=checks.map((x,i)=>`<label class="check-row"><input type="checkbox" data-check="${i}" ${checked.includes(i)?'checked':''}><span><b>${x[0]}</b><small>${x[1]}</small></span><span>0${i+1}</span></label>`).join('');function progress(){let n=checked.length;$('#percent').textContent=Math.round(n/6*100)+'%';$('#completed').textContent=n+' / 6 준비 완료';$('#bar').style.width=n/6*100+'%'}progress();$('#checklist').addEventListener('change',e=>{let i=+e.target.dataset.check;checked=e.target.checked?[...new Set([...checked,i])]:checked.filter(x=>x!==i);save('safekit-check',checked);progress()});
const art=[`<path d="M35 20h80l7 112H28z" fill="#bab39b"/><path d="M36 28h78M31 122h88" stroke="#5b5b4a" stroke-width="4"/><text x="75" y="64" text-anchor="middle" font-size="10" fill="#303729">EMERGENCY</text><text x="75" y="83" text-anchor="middle" font-size="18" font-weight="bold" fill="#303729">FOOD</text><path d="M55 100h40" stroke="#d13b32" stroke-width="7"/>`,`<g transform="rotate(-30 75 75)"><rect x="59" y="47" width="32" height="92" rx="5" fill="#62695a"/><path d="M47 20h56l-8 43H55z" fill="#343b30" stroke="#8a9380"/><ellipse cx="75" cy="20" rx="28" ry="9" fill="#d0d8ba"/><path d="M63 83h24m-24 8h24m-24 8h24m-24 8h24" stroke="#30362b" stroke-width="4"/></g>`,`<rect x="17" y="37" width="116" height="87" rx="13" fill="#b63630" stroke="#ef6257"/><path d="M55 36v-9q20-12 40 0v9" fill="none" stroke="#b63630" stroke-width="8"/><path d="M75 56v46m-23-23h46" stroke="#f0ebe2" stroke-width="14"/>`,`<path d="M58 35V20q17-16 34 0v15" fill="none" stroke="#5d6451" stroke-width="8"/><rect x="31" y="28" width="88" height="111" rx="23" fill="#424b36" stroke="#7e896d"/><rect x="42" y="80" width="66" height="47" rx="8" fill="#2a3223" stroke="#747e61"/><path d="M49 91h52" stroke="#9ba68d"/><rect x="60" y="51" width="30" height="19" fill="#d83b32"/><path d="M75 55v11m-5-5h10" stroke="white" stroke-width="3"/>`];
const products=[{name:'비상식량 데일리 팩',cat:'식량·식수',desc:'차근차근 준비하는 식량 비축',price:18900},{name:'LED 비상 손전등',cat:'조명·통신',desc:'정전에 대비하는 기본 조명',price:24900},{name:'패밀리 구급 파우치',cat:'응급·위생',desc:'한곳에 모아두는 기본 응급용품',price:29900},{name:'에센셜 비상 배낭 키트',cat:'비상 키트',desc:'나에게 맞춰 채우는 비상 배낭',price:89000}];function render(filter='전체'){$('#products').innerHTML=products.map((p,i)=>filter==='전체'||p.cat===filter?`<article class="product"><div class="product-art"><span>DEMO PRODUCT</span><svg viewBox="0 0 150 150" aria-label="${p.name}" role="img">${art[i]}</svg></div><div class="product-category">${p.cat}</div><h3>${p.name}</h3><p>${p.desc}</p><div class="price-row"><strong>${won(p.price)}</strong><button data-add="${i}" aria-label="${p.name} 담기">+</button></div></article>`:'').join('')}render();document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');render(b.dataset.filter)});let timer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}$('#products').onclick=e=>{let b=e.target.closest('[data-add]');if(!b)return;let id=b.dataset.add;cart[id]=(cart[id]||0)+1;updateCart();toast('장바구니에 담았습니다')};function updateCart(){save('safekit-cart',cart);$('#count').textContent=Object.values(cart).reduce((a,b)=>a+b,0);$('#cartItems').innerHTML=Object.entries(cart).length?Object.entries(cart).map(([i,n])=>`<div class="cart-row"><span>${products[i].name}<small style="display:block;margin-top:7px;color:#9ca88b">${won(products[i].price*n)}</small></span><button data-change="${i}" data-delta="-1" aria-label="수량 줄이기">−</button>${n}<button data-change="${i}" data-delta="1" aria-label="수량 늘리기">+</button></div>`).join(''):'<p>아직 담긴 상품이 없습니다.</p>';$('#total').textContent=won(Object.entries(cart).reduce((s,[i,n])=>s+products[i].price*n,0))}updateCart();$('.cart-toggle').onclick=()=>$('#cart').showModal();$('#cartItems').onclick=e=>{let b=e.target.closest('[data-change]');if(!b)return;let i=b.dataset.change;cart[i]+=+b.dataset.delta;if(cart[i]<=0)delete cart[i];updateCart()};$('#clear').onclick=()=>{cart={};updateCart()};const guides=[['경보가 울렸을 때','재난문자와 정부·지자체의 공식 방송을 확인하세요.\n경보 종류와 상황에 따른 안내를 듣고, 현장 통제에 따라 행동하세요.\n확인되지 않은 정보를 퍼뜨리지 말고 가족과 필요한 정보를 공유하세요.'],['대피하기 전','평소 집과 직장 주변의 공식 대피소 위치와 이동 경로를 확인하세요.\n가족이 떨어져 있을 때 연락할 방법과 만날 장소를 정해두세요.\n실제 대피는 경보와 현장 안내에 따라 진행하세요.'],['평소에 준비하기','식량·식수, 조명, 통신, 구급·위생용품을 점검하세요.\n휴대할 물품은 이동하기 편한 가방에 모아두고 가족에게 위치를 알려주세요.\n식품의 유통기한과 건전지 상태를 정기적으로 확인하고 교체하세요.']];document.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>{let g=guides[b.dataset.guide];$('#guideTitle').textContent=g[0];$('#guideBody').textContent=g[1];$('#guideModal').showModal()});document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){let r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
